import json, os, pathlib, subprocess
COMMITS = json.loads('[["2026-02-03T09:30:00", "Initial import", {"README.md": "# deskline\\n\\nHelp-desk tickets from the command line. Node 20 or newer, no dependencies.\\n\\n## Usage\\n\\nThe command line is the public interface: the support dashboard shells out to it and parses the JSON it prints.\\n\\n```sh\\nnode src/cli.js list --status open\\nnode src/cli.js list --overdue true\\nnode src/cli.js show --id 3\\nnode src/cli.js create --title \\"Printer on fire\\" --priority urgent --requester u-ana\\nnode src/cli.js assign --id 3 --user u-ben\\nnode src/cli.js close --id 3\\nnode src/cli.js stats\\n```\\n\\nEvery command accepts `--data <file>` (default `data/desk.json`) and `--now <ISO time>` (default: the current time).\\nCommands print JSON on success. On failure they print `error: ...` to stderr and exit with code 2.\\n`create`, `assign` and `close` print the resulting ticket; they do not write to the data file.\\n\\nEverything under `src/` is internal.\\n\\n## Tests\\n\\n```sh\\nnpm test\\n```\\n", "data/desk.json": "{\\n  \\"users\\": [\\n    {\\"id\\": \\"u-ana\\", \\"name\\": \\"Ana Duarte\\", \\"email\\": \\"ana@deskline.example\\", \\"active\\": true},\\n    {\\"id\\": \\"u-ben\\", \\"name\\": \\"Ben Okafor\\", \\"email\\": \\"ben@deskline.example\\", \\"active\\": true},\\n    {\\"id\\": \\"u-cas\\", \\"name\\": \\"Cas de Wit\\", \\"email\\": \\"cas@deskline.example\\", \\"active\\": false},\\n    {\\"id\\": \\"u-bot\\", \\"name\\": \\"Triage bot\\", \\"email\\": \\"bot@deskline.example\\", \\"active\\": true}\\n  ],\\n  \\"tickets\\": [\\n    {\\"id\\": 1, \\"title\\": \\"Cannot log in after password reset\\", \\"priority\\": \\"high\\", \\"status\\": \\"open\\", \\"requester\\": \\"u-ana\\", \\"assignee\\": null, \\"createdAt\\": \\"2026-10-04T08:15:00.000Z\\"},\\n    {\\"id\\": 2, \\"title\\": \\"Invoice PDF shows the wrong VAT number\\", \\"priority\\": \\"normal\\", \\"status\\": \\"pending\\", \\"requester\\": \\"u-ben\\", \\"assignee\\": \\"u-ana\\", \\"createdAt\\": \\"2026-10-01T13:40:00.000Z\\"},\\n    {\\"id\\": 3, \\"title\\": \\"Export times out for large accounts\\", \\"priority\\": \\"urgent\\", \\"status\\": \\"open\\", \\"requester\\": \\"u-ben\\", \\"assignee\\": null, \\"createdAt\\": \\"2026-10-05T07:30:00.000Z\\"},\\n    {\\"id\\": 4, \\"title\\": \\"Typo on the pricing page\\", \\"priority\\": \\"low\\", \\"status\\": \\"closed\\", \\"requester\\": \\"u-ana\\", \\"assignee\\": \\"u-ben\\", \\"createdAt\\": \\"2026-09-20T10:00:00.000Z\\", \\"closedAt\\": \\"2026-09-22T09:00:00.000Z\\"},\\n    {\\"id\\": 5, \\"title\\": \\"Webhook retries arrive out of order\\", \\"priority\\": \\"high\\", \\"status\\": \\"pending\\", \\"requester\\": \\"u-cas\\", \\"assignee\\": \\"u-ben\\", \\"createdAt\\": \\"2026-10-03T16:05:00.000Z\\"},\\n    {\\"id\\": 6, \\"title\\": \\"Add SSO for the staging tenant\\", \\"priority\\": \\"low\\", \\"status\\": \\"open\\", \\"requester\\": \\"u-ana\\", \\"assignee\\": \\"u-ana\\", \\"createdAt\\": \\"2026-09-28T09:00:00.000Z\\"},\\n    {\\"id\\": 7, \\"title\\": \\"Search returns archived projects\\", \\"priority\\": \\"normal\\", \\"status\\": \\"open\\", \\"requester\\": \\"u-ben\\", \\"assignee\\": null, \\"createdAt\\": \\"2026-10-04T15:20:00.000Z\\"},\\n    {\\"id\\": 8, \\"title\\": \\"Two-factor codes rejected on mobile\\", \\"priority\\": \\"urgent\\", \\"status\\": \\"closed\\", \\"requester\\": \\"u-ana\\", \\"assignee\\": \\"u-ana\\", \\"createdAt\\": \\"2026-10-02T11:00:00.000Z\\", \\"closedAt\\": \\"2026-10-02T12:30:00.000Z\\"},\\n    {\\"id\\": 9, \\"title\\": \\"Imported from the old tracker\\", \\"priority\\": \\"critical\\", \\"status\\": \\"open\\", \\"requester\\": \\"u-cas\\", \\"assignee\\": null, \\"createdAt\\": \\"2026-08-30T09:00:00.000Z\\"}\\n  ]\\n}\\n", "package.json": "{\\n  \\"name\\": \\"deskline\\",\\n  \\"version\\": \\"0.6.0\\",\\n  \\"private\\": true,\\n  \\"type\\": \\"module\\",\\n  \\"scripts\\": {\\n    \\"test\\": \\"node --test\\"\\n  },\\n  \\"engines\\": {\\n    \\"node\\": \\">=20\\"\\n  }\\n}\\n", "src/cli.js": "import { setNow } from \\"./clock.js\\";\\nimport { loadStore } from \\"./store.js\\";\\nimport * as tickets from \\"./controllers/ticketController.js\\";\\nimport { stats } from \\"./controllers/statsController.js\\";\\n\\nfunction parse(argv) {\\n  const [command, ...rest] = argv;\\n  const args = {};\\n  for (let i = 0; i < rest.length; i += 2) {\\n    if (!rest[i].startsWith(\\"--\\") || rest[i + 1] === undefined) {\\n      throw new Error(`bad argument: ${rest[i]}`);\\n    }\\n    args[rest[i].slice(2)] = rest[i + 1];\\n  }\\n  return { command, args };\\n}\\n\\nfunction main(argv) {\\n  const { command, args } = parse(argv);\\n  loadStore(args.data ?? \\"data/desk.json\\");\\n  setNow(args.now);\\n\\n  let result;\\n  if (command === \\"list\\") {\\n    result = tickets.list(args);\\n  } else if (command === \\"show\\") {\\n    result = tickets.show(args);\\n  } else if (command === \\"create\\") {\\n    result = tickets.create(args);\\n  } else if (command === \\"assign\\") {\\n    result = tickets.assign(args);\\n  } else if (command === \\"close\\") {\\n    result = tickets.close(args);\\n  } else if (command === \\"stats\\") {\\n    result = stats();\\n  } else {\\n    throw new Error(`unknown command: ${command}`);\\n  }\\n  console.log(JSON.stringify(result));\\n}\\n\\ntry {\\n  main(process.argv.slice(2));\\n} catch (err) {\\n  console.error(`error: ${err.message}`);\\n  process.exitCode = 2;\\n}\\n", "src/clock.js": "// The CLI sets the time once; services ask for it when they need it.\\nlet current = null;\\n\\nexport function setNow(iso) {\\n  current = iso ? new Date(iso) : null;\\n}\\n\\nexport function getNow() {\\n  return current ?? new Date();\\n}\\n", "src/controllers/statsController.js": "import { store } from \\"../store.js\\";\\nimport { getNow } from \\"../clock.js\\";\\n\\nconst ORDER = [\\"high\\", \\"normal\\", \\"low\\"];\\nconst HOURS = { high: 36, normal: 48, low: 120 };\\n\\nexport function stats() {\\n  const byStatus = { open: 0, pending: 0, closed: 0 };\\n  const byPriority = {};\\n  for (const priority of ORDER) {\\n    byPriority[priority] = 0;\\n  }\\n  let overdue = 0;\\n\\n  for (const ticket of store._tickets) {\\n    try {\\n      byStatus[ticket.status] += 1;\\n      byPriority[ticket.priority] += 1;\\n      {\\n        const due = new Date(ticket.createdAt).getTime() + HOURS[ticket.priority] * 3600000;\\n        if (getNow().getTime() > due) {\\n          overdue += 1;\\n        }\\n      }\\n    } catch {\\n      continue;\\n    }\\n  }\\n\\n  return { byStatus, byPriority, overdue, total: store._tickets.length };\\n}\\n", "src/controllers/ticketController.js": "import { store } from \\"../store.js\\";\\nimport { validateCreate, validateFilter } from \\"../validators/ticketValidator.js\\";\\nimport { listTickets, createTicket, assignTicket, closeTicket } from \\"../services/ticketService.js\\";\\nimport { formatTicket } from \\"../formatters/ticketFormatter.js\\";\\n\\nexport function list(args) {\\n  const filter = { status: args.status, priority: args.priority, assignee: args.assignee, overdue: args.overdue === \\"true\\" };\\n  validateFilter(filter);\\n  return listTickets(filter).map(formatTicket);\\n}\\n\\nexport function show(args) {\\n  const ticket = store._tickets.find((t) => t.id === Number(args.id));\\n  if (!ticket) {\\n    throw new Error(`ticket ${args.id} not found`);\\n  }\\n  return formatTicket(ticket);\\n}\\n\\nexport function create(args) {\\n  const input = { title: args.title, priority: args.priority ?? \\"normal\\", requester: args.requester };\\n  validateCreate(input);\\n  const ticket = createTicket(input);\\n  return formatTicket(ticket);\\n}\\n\\nexport function assign(args) {\\n  return formatTicket(assignTicket(Number(args.id), args.user));\\n}\\n\\nexport function close(args) {\\n  return formatTicket(closeTicket(Number(args.id)));\\n}\\n", "src/formatters/ticketFormatter.js": "import { dueAt, isOverdue } from \\"../services/slaService.js\\";\\n\\nexport function priorityLabel(priority) {\\n  switch (priority) {\\n    case \\"high\\":\\n      return \\"High (P2)\\";\\n    case \\"normal\\":\\n      return \\"Normal (P3)\\";\\n    case \\"low\\":\\n      return \\"Low (P4)\\";\\n    default:\\n      return priority;\\n  }\\n}\\n\\nexport function statusLabel(status) {\\n  if (status === \\"open\\") {\\n    return \\"Open\\";\\n  } else if (status === \\"pending\\") {\\n    return \\"Pending\\";\\n  } else if (status === \\"closed\\") {\\n    return \\"Closed\\";\\n  }\\n  return status;\\n}\\n\\nexport function formatTicket(ticket) {\\n  return {\\n    id: ticket.id,\\n    title: ticket.title,\\n    priority: priorityLabel(ticket.priority),\\n    status: statusLabel(ticket.status),\\n    assignee: ticket.assignee ?? \\"unassigned\\",\\n    dueAt: dueAt(ticket),\\n    overdue: isOverdue(ticket),\\n  };\\n}\\n", "src/services/slaService.js": "import { getNow } from \\"../clock.js\\";\\nimport { isOpen } from \\"./ticketService.js\\";\\n\\nexport function slaHours(priority) {\\n  switch (priority) {\\n    case \\"high\\":\\n      return 36;\\n    case \\"normal\\":\\n      return 48;\\n    case \\"low\\":\\n      return 120;\\n    default:\\n      return 48;\\n  }\\n}\\n\\nexport function dueAt(ticket) {\\n  const created = new Date(ticket.createdAt).getTime();\\n  return new Date(created + slaHours(ticket.priority) * 3600000).toISOString();\\n}\\n\\nexport function isOverdue(ticket) {\\n  if (!isOpen(ticket)) {\\n    return false;\\n  }\\n  return getNow().getTime() > new Date(dueAt(ticket)).getTime();\\n}\\n", "src/services/ticketService.js": "import { store, nextId } from \\"../store.js\\";\\nimport { getNow } from \\"../clock.js\\";\\nimport { getUser } from \\"./userService.js\\";\\nimport { isOverdue } from \\"./slaService.js\\";\\n\\nexport function isOpen(ticket) {\\n  return ticket.status !== \\"closed\\";\\n}\\n\\nexport function listTickets(filter = {}) {\\n  let out = store._tickets.slice();\\n  if (filter.status) {\\n    out = out.filter((t) => t.status === filter.status);\\n  }\\n  if (filter.priority) {\\n    out = out.filter((t) => t.priority === filter.priority);\\n  }\\n  if (filter.assignee) {\\n    out = out.filter((t) => t.assignee === filter.assignee);\\n  }\\n  if (filter.overdue) {\\n    out = out.filter((t) => isOverdue(t));\\n  }\\n  return out.sort((a, b) => a.id - b.id);\\n}\\n\\nexport function getTicket(id) {\\n  const ticket = store._tickets.find((t) => t.id === id);\\n  if (!ticket) {\\n    throw new Error(`ticket ${id} not found`);\\n  }\\n  return ticket;\\n}\\n\\nexport function createTicket(input) {\\n  return {\\n    id: nextId(),\\n    title: input.title,\\n    priority: input.priority,\\n    status: \\"open\\",\\n    requester: input.requester,\\n    assignee: null,\\n    createdAt: getNow().toISOString(),\\n  };\\n}\\n\\nexport function assignTicket(id, userId) {\\n  const ticket = getTicket(id);\\n  const user = getUser(userId);\\n  if (!user) {\\n    throw new Error(`user ${userId} not found`);\\n  }\\n  if (!user.active) {\\n    throw new Error(`user ${userId} is inactive`);\\n  }\\n  return { ...ticket, assignee: user.id, status: ticket.status === \\"open\\" ? \\"pending\\" : ticket.status };\\n}\\n\\nexport function closeTicket(id) {\\n  const ticket = getTicket(id);\\n  if (ticket.status === \\"closed\\") {\\n    throw new Error(\\"ticket is already closed\\");\\n  }\\n  if (ticket.status === \\"open\\" && !ticket.assignee) {\\n    throw new Error(\\"cannot close an unassigned ticket\\");\\n  }\\n  return { ...ticket, status: \\"closed\\", closedAt: getNow().toISOString() };\\n}\\n", "src/services/userService.js": "import { store } from \\"../store.js\\";\\n\\nexport function getUser(id) {\\n  return store._users.find((u) => u.id === id) ?? null;\\n}\\n\\nexport function listUsers() {\\n  return store._users.slice();\\n}\\n\\nexport function findByEmail(email) {\\n  return store._users.find((u) => u.email.toLowerCase() === email.toLowerCase()) ?? null;\\n}\\n", "src/store.js": "import { readFileSync } from \\"node:fs\\";\\n\\nexport const store = { _tickets: [], _users: [], loaded: false };\\n\\nexport function loadStore(path) {\\n  const raw = JSON.parse(readFileSync(path, \\"utf8\\"));\\n  store._tickets = raw.tickets;\\n  store._users = raw.users;\\n  store.loaded = true;\\n}\\n\\nexport function nextId() {\\n  return store._tickets.reduce((max, t) => Math.max(max, t.id), 0) + 1;\\n}\\n", "src/utils/legacyExport.js": "// CSV export for the old reporting tool.\\nexport function toCsv(tickets) {\\n  const header = \\"id,title,priority,status\\";\\n  const rows = tickets.map((t) => [t.id, JSON.stringify(t.title), t.priority, t.status].join(\\",\\"));\\n  return [header, ...rows].join(\\"\\\\n\\");\\n}\\n", "src/validators/ticketValidator.js": "const PRIORITIES = [\\"low\\", \\"normal\\", \\"high\\"];\\nconst STATUSES = [\\"open\\", \\"pending\\", \\"closed\\"];\\n\\nexport function validateCreate(input) {\\n  const errors = [];\\n  if (!input.title || input.title.trim() === \\"\\") {\\n    errors.push(\\"title is required\\");\\n  } else if (input.title.length > 120) {\\n    errors.push(\\"title is longer than 120 characters\\");\\n  }\\n  if (!PRIORITIES.includes(input.priority)) {\\n    errors.push(`priority must be one of ${PRIORITIES.join(\\", \\")}`);\\n  }\\n  if (!input.requester) {\\n    errors.push(\\"requester is required\\");\\n  }\\n  if (errors.length > 0) {\\n    throw new Error(errors.join(\\"; \\"));\\n  }\\n}\\n\\nexport function validateFilter(filter) {\\n  if (filter.status && !STATUSES.includes(filter.status)) {\\n    throw new Error(`status must be one of ${STATUSES.join(\\", \\")}`);\\n  }\\n  if (filter.priority && !PRIORITIES.includes(filter.priority)) {\\n    throw new Error(`priority must be one of ${PRIORITIES.join(\\", \\")}`);\\n  }\\n}\\n", "test/ticketService.test.js":